{
  "story": "How can a function call itself and still finish? Start with factorial of three. Each call saves its multiplication and requests a smaller input, until one returns directly. Compare descending calls with returning results: waiting callers resume rather than restart. Use Next to reach the outer result, which remains visible.",
  "aha": {
    "stateId": "outer-return",
    "observation": "The base case stops further calls; each waiting caller then resumes its saved multiplication using the returned result."
  },
  "layout": {
    "preset": "approved-card",
    "width": 640
  },
  "parts": [
    {
      "id": "call-rail",
      "kind": "step-rail",
      "presentation": "Place below the story and above the experiment. Show the active state and completed trace here, without a separate progress display.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "call-map",
      "kind": "fixed-picture",
      "presentation": "Use the canonical algorithm composition with three fixed call regions in declared order. Inactive regions show the call map, not executed calls. Highlight only active regions; keep labels readable throughout. Links identify smaller self-calls, not elapsed time.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "active-explanation",
      "kind": "active-callout",
      "presentation": "Anchor beside the active call without covering labels. Identify where execution is happening; leave numerical values in the readouts.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "execution-readouts",
      "kind": "value-readout",
      "presentation": "Place below the picture with a bound status line. Fixed input: positive integer three. Base case: factorial of one returns one. Arithmetic is exact and unitless. Operation and saved work describe the same selected state; no measurements or clock are used.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "label": "Step",
      "items": "variant.states",
      "presentation": "Navigation budget: one index control and Reset; parameter-control budget: zero. Use Previous and Next, defaulting to the first state. Advance one state within the first-to-last bounds. Retain button names when disabled at boundaries. Every state persists until learner action, including the aha state. Provide keyboard operation and visible focus."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and fixed input. Provide keyboard operation and visible focus."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Factorial: smaller calls, then returned results",
        "regions": [
          {
            "id": "outer",
            "label": "Outer call",
            "values": [
              "Save the input; request a smaller self-call.",
              "Resume by multiplying the saved input by the returned result."
            ]
          },
          {
            "id": "middle",
            "label": "Middle call",
            "values": [
              "Save the input; request a smaller self-call.",
              "Resume by multiplying the saved input by the returned result."
            ]
          },
          {
            "id": "base",
            "label": "Base call",
            "values": [
              "Return directly at the base case.",
              "Do not request another self-call."
            ]
          }
        ],
        "links": [
          {
            "from": "outer",
            "to": "middle",
            "label": "Same function, smaller input"
          },
          {
            "from": "middle",
            "to": "base",
            "label": "Same function, smaller input"
          }
        ],
        "states": [
          {
            "id": "outer-start",
            "label": "Enter Outer call",
            "short": "Outer enters",
            "sentence": "Outer call starts the recursive computation.",
            "why": "It must obtain a smaller call's result before completing its multiplication.",
            "active": [
              "outer"
            ],
            "calloutRegion": "outer",
            "readouts": [
              {
                "id": "operation",
                "label": "Current operation",
                "value": "Evaluate factorial(3)"
              },
              {
                "id": "saved-work",
                "label": "Suspended callers",
                "value": "None yet"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Descending: ready to request a smaller self-call."
              }
            ]
          },
          {
            "id": "middle-start",
            "label": "Enter Middle call",
            "short": "Middle enters",
            "sentence": "Middle call runs while Outer call waits.",
            "why": "Calling the same function creates another invocation; it does not erase the waiting caller's saved work.",
            "active": [
              "middle"
            ],
            "calloutRegion": "middle",
            "readouts": [
              {
                "id": "operation",
                "label": "Current operation",
                "value": "Evaluate factorial(2)"
              },
              {
                "id": "saved-work",
                "label": "Suspended callers",
                "value": "Outer call: multiply the returned result by 3"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Descending: Outer call is suspended; Middle call requests a smaller self-call."
              }
            ]
          },
          {
            "id": "base-return",
            "label": "Base call returns",
            "short": "Base returns",
            "sentence": "Base call returns directly instead of calling itself again.",
            "why": "The smaller inputs have reached the stopping condition; waiting callers can now resume.",
            "active": [
              "base"
            ],
            "calloutRegion": "base",
            "readouts": [
              {
                "id": "operation",
                "label": "Current operation",
                "value": "factorial(1) = 1"
              },
              {
                "id": "saved-work",
                "label": "Suspended callers",
                "value": "Resume order: Middle call ×2; then Outer call ×3"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Turning point: no further self-call; return to Middle call."
              }
            ]
          },
          {
            "id": "middle-return",
            "label": "Resume Middle call",
            "short": "Middle resumes",
            "sentence": "Middle call resumes its saved multiplication rather than starting over.",
            "why": "The returned result replaces the smaller self-call in the waiting calculation.",
            "active": [
              "middle"
            ],
            "calloutRegion": "middle",
            "readouts": [
              {
                "id": "operation",
                "label": "Current operation",
                "value": "2 × 1 = 2"
              },
              {
                "id": "saved-work",
                "label": "Suspended callers",
                "value": "Outer call: multiply the returned result by 3"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Returning: Middle call finishes and returns its result to Outer call."
              }
            ]
          },
          {
            "id": "outer-return",
            "label": "Resume Outer call",
            "short": "Outer finishes",
            "sentence": "Outer call resumes its saved multiplication and finishes.",
            "why": "The base case enabled a chain of returns; each caller continued with the result it had awaited.",
            "active": [
              "outer"
            ],
            "calloutRegion": "outer",
            "readouts": [
              {
                "id": "operation",
                "label": "Current operation",
                "value": "3 × 2 = 6"
              },
              {
                "id": "saved-work",
                "label": "Suspended callers",
                "value": "None"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Complete: all calls returned; the final result remains visible."
              }
            ]
          }
        ]
      }
    ]
  }
}
